SELECT 
FROM TBL_ACCOUNT_INFO
WHERE ISDELETED = 0

    AND ORGID = #{params.orgId}


    AND ACCOUNTNUMBER LIKE CONCAT('%', #{params.accountNumber}, '%')


    AND ACCOUNTNAME LIKE CONCAT('%', #{params.accountName}, '%')


    AND ACCOUNTTYPE = #{params.accountType}


    AND BANKCODE = #{params.bankCode}


    AND CURRENCYCODE = #{params.currencyCode}


    AND ACCOUNTSTATUS = #{params.accountStatus}

ORDER BY CREATETIME DESC

SELECT 
FROM TBL_ACCOUNT_INFO
WHERE ACCOUNTNUMBER = #{accountNumber}
AND ORGID = #{orgId}
AND ISDELETED = 0

SELECT 
FROM TBL_ACCOUNT_INFO
WHERE BANKCODE = #{bankCode}
AND ORGID = #{orgId}
AND ISDELETED = 0
ORDER BY CREATETIME DESC

SELECT 
FROM TBL_ACCOUNT_INFO
WHERE CURRENCYCODE = #{currencyCode}
AND ORGID = #{orgId}
AND ISDELETED = 0
ORDER BY CREATETIME DESC

SELECT COUNT(1)
FROM TBL_ACCOUNT_INFO
WHERE ISDELETED = 0

    AND ORGID = #{params.orgId}


    AND ACCOUNTTYPE = #{params.accountType}


    AND BANKCODE = #{params.bankCode}


    AND CURRENCYCODE = #{params.currencyCode}


    AND ACCOUNTSTATUS = #{params.accountStatus}

SELECT 
FROM TBL_ACCOUNT_INFO
WHERE ISDELETED = 0

    AND ORGID = #{params.orgId}


    AND ACCOUNTNUMBER LIKE CONCAT('%', #{params.accountNumber}, '%')


    AND ACCOUNTNAME LIKE CONCAT('%', #{params.accountName}, '%')


    AND ACCOUNTTYPE = #{params.accountType}


    AND BANKCODE = #{params.bankCode}


    AND CURRENCYCODE = #{params.currencyCode}


    AND ACCOUNTSTATUS = #{params.accountStatus}

ORDER BY CREATETIME DESC

SELECT BANKCODE as bankCode, BANKNAME as bankName, COUNT(*) as accountCount FROM TBL_ACCOUNT_INFO WHERE ISDELETED = 0
AND ORGID = #{orgId}
GROUP BY BANKCODE, BANKNAME ORDER BY accountCount DESC
